$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '../game-session.ps1')
function Check($Actual,$Expected,[string]$Reason){if($Actual -ne $Expected){throw $Reason}}
$entry='[ZB] class com.pavelvoronin.pz3d.entry.Main: method main() invoked successfully'
$signed='[ZB] ZBS verification valid for C:\owned\mods\pz3d\42.20.4\media\java\PZ3D-0.7.2.jar: uploaderID=N/A'
$started='[pz3d] Java prototype 0.7.2 loaded; patch targets resolved; view key: Options'
Check (Test-ModStudioLoaderOwner ($signed+"`n"+$started) $entry 'ZombieBuddy') $true 'Current signed native entry must pass'
Check (Test-ModStudioLoaderOwner ($signed+"`n"+$started) $entry 'Pz3dLoader') $false 'Native entry cannot prove custom loader ownership'
Check (Test-ModStudioLoaderOwner $started $entry 'ZombieBuddy') $false 'Unsigned startup must fail'
Check (Test-ModStudioLoaderOwner $signed $entry 'ZombieBuddy') $false 'Missing successful pz3d startup must fail'
Check (Test-ModStudioLoaderOwner ($signed+"`n"+$started) '' 'ZombieBuddy') $false 'Missing successful entry invocation must fail'
Check (Test-ModStudioLoaderOwner ($signed.Replace('mods\pz3d','mods\other')+"`n"+$started) $entry 'ZombieBuddy') $false 'Other mod signature must fail'
Check (Test-ModStudioLoaderOwner ($signed.Replace('verification valid','verification invalid')+"`n"+$started) $entry 'ZombieBuddy') $false 'Invalid signature must fail'
Check (Test-ModStudioLoaderOwner ($signed+"`n"+$started) ($entry.Replace('pz3d.entry','other.entry')) 'ZombieBuddy') $false 'Other entry must fail'
Check (Test-ModStudioLoaderOwner "owner=Pz3dLoader`n" '' 'Pz3dLoader') $true 'Explicit legacy ownership remains supported'
Check (Test-ModStudioLoaderOwner "owner=ZombieBuddy`n" '' 'Pz3dLoader') $false 'Wrong explicit owner must fail'
Check (Test-ModStudioLoaderOwner ("owner=Pz3dLoader`n"+$signed+"`n"+$started) $entry 'ZombieBuddy') $false 'Fallback must not override a conflicting owner'
Check (Test-ModStudioLoaderOwner "owner=ZombieBuddy`nowner=Pz3dLoader`n" '' 'ZombieBuddy') $false 'Conflicting explicit owners must fail'
Write-Output 'PASS: signed native entry evidence, legacy ownership and rejected incomplete or conflicting startup evidence.'
